<?php require_once __DIR__.'/../../includes/auth.php';requireHOD();$id=(int)($_GET['id']??0);$q=db()->prepare('SELECT * FROM batches WHERE id=? AND department_id=?');$q->execute([$id,$_SESSION['user']['department_id']]);$b=$q->fetch();if(!$b)redirect('/hod/batches/index.php');if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();db()->prepare('UPDATE batches SET batch_name=?,batch_code=?,academic_year=?,status=? WHERE id=?')->execute([trim($_POST['name']),trim($_POST['code']),trim($_POST['year']),$_POST['status'],$id]);flash('Batch updated.');redirect('/hod/batches/index.php');}$title='Edit Batch';require __DIR__.'/../../includes/header.php';?><section class="panel"><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Name<input name="name" value="<?=e($b['batch_name'])?>" required></label><label>Code<input name="code" value="<?=e($b['batch_code'])?>" required></label><label>Year<input name="year" value="<?=e($b['academic_year'])?>" required></label><label>Status<select name="status"><option><?=e($b['status'])?></option><option value="<?=$b['status']==='active'?'inactive':'active'?>"><?=$b['status']==='active'?'inactive':'active'?></option></select></label><button>Update Batch</button></form></section><?php require __DIR__.'/../../includes/footer.php';?>
